const TV_TEMPLATES:{category:string;slide:Slide}[]=ONZETROTS_TV_TEMPLATES.map(({category,name,content})=>({category,slide:{...BASE,id:`tv-${content.kind}`,name,title:content.title,time:content.time??'',subtitle:content.subtitle??'',location:content.location??'',photo:content.background??'',color:'#123f8d',background:'#063893',clubName:content.clubName,logo:content.logo,themeId:'onzetrots-tv',tv:content,overlay:20,duration:15}}));
export function studioTvContent(slide:Slide):OnzeTrotsTvContent{const content:OnzeTrotsTvContent={kind:'generic',rows:[],...slide.tv,title:slide.title,time:slide.time,subtitle:slide.subtitle,location:slide.location,background:slide.photo,clubName:slide.clubName??slide.tv?.clubName,logo:slide.logo??slide.tv?.logo,overlay:slide.overlay??slide.tv?.overlay??20,align:slide.align};if(content.kind==='uitslagen'){const featured=content.rows.find(row=>row.own)??content.rows[0];content.match=featured?{home:featured.home||featured.primary,away:featured.away||featured.secondary||'',homeScore:featured.homeScore,awayScore:featured.awayScore,label:content.values?.[0]}:undefined;}return content;}
const TV_ROWS_PER_PAGE:Partial<Record<OnzeTrotsTvContent['kind'],number>>={programma:8,uitslagen:8,stand:8,kantine:12,clubnieuws:3,partners:6,generic:6};
export function studioSlidePages(slide:Slide){if(slide.themeId!=='onzetrots-tv'||!slide.tv)return 1;return Math.max(1,Math.ceil(slide.tv.rows.length/(TV_ROWS_PER_PAGE[slide.tv.kind]??12)));}
export function studioSlideDuration(slide:Slide){return slide.duration*studioSlidePages(slide);}
function ThemedStudioCanvas({slide,selected,playing}:{slide:Slide;selected:boolean;playing:boolean}){
 const[page,setPage]=useState(0);const pages=studioSlidePages(slide);const base=studioTvContent(slide);const pageSize=TV_ROWS_PER_PAGE[base.kind]??12;const current=Math.min(page,pages-1);
 useEffect(()=>{setPage(0)},[slide.id,slide.tv?.kind]);
 useEffect(()=>{if(!playing||pages<2)return;const timer=setInterval(()=>setPage(value=>(value+1)%pages),Math.max(3,slide.duration)*1000);return()=>clearInterval(timer)},[playing,pages,slide.duration,slide.id]);
 return <div className={`${s.tvCanvas} ${slide.orientation==='portrait'?s.tvPortrait:''}`}><OnzeTrotsTvPreview content={{...base,rows:base.rows.slice(current*pageSize,(current+1)*pageSize),page:current,pages}} orientation={slide.orientation} active={playing}/>{selected&&pages>1&&<div className={s.tvPageControl}><button type="button" aria-label="Vorige gegevenspagina" disabled={current===0} onClick={()=>setPage(current-1)}><ArrowLeft size={15}/></button><span>{current+1} / {pages}</span><button type="button" aria-label="Volgende gegevenspagina" disabled={current===pages-1} onClick={()=>setPage(current+1)}><ArrowRight size={15}/></button></div>}</div>
}
